    make(3, "水平桌面上的小車正向右等速滑行。若忽略空氣阻力，以下哪個受力描述最合理？", {"A": "一定有一個向右的維持運動力", "B": "重力與支持力可互相抵消，水平方向合力可為零", "C": "只有向左摩擦力，所以小車必減速", "D": "小車沒有受到任何力"}, "B", "等速直線運動表示合力為零，不表示所有力消失；垂直方向重力與支持力抵消，理想忽略摩擦時水平方向也可無合力。", "把單一力與合力分開，逐方向檢查受力是否抵消。", ["列出向下重力與向上支持力。", "確認兩力大小可互相抵消。", "忽略摩擦與空氣阻力後，水平方向沒有未抵消力。", "因此總合力為零而小車仍可等速前進。", "所以選 B。"], "medium"),
    make(4, "書本靜止放在水平桌面上。下列哪個敘述正確？", {"A": "書本沒有受力，所以保持靜止", "B": "重力與桌面支持力大小相等、方向相反，使合力為零", "C": "桌面支持力大於重力，所以書本向上加速", "D": "重力不存在，只有支持力存在"}, "B", "書本仍受向下重力與向上支持力；兩者抵消後合力為零，因此維持靜止。", "畫自由體圖，確認『合力為零』不等於『沒有任何力』。", ["列出書本受到的重力。", "列出桌面提供的向上支持力。", "因書本靜止，垂直方向合力為零。", "所以兩力大小相等、方向相反。", "所以選 B。"], "easy"),
    make(5, "滑板車在粗糙地面上停止踩踏後逐漸減速。造成速度改變的主要原因為何？", {"A": "慣性本身會把速度消耗掉", "B": "地面摩擦與空氣阻力形成反向合力", "C": "物體運動就會自動產生向後重力", "D": "合力仍為零但速度必然下降"}, "B", "若速度變小表示有加速度，必有不為零的合力；此情境中地面摩擦和空氣阻力大致反向運動方向，造成減速。", "先由速度改變判斷合力不為零，再找出實際阻力來源。", ["觀察滑板車速度由大變小。", "速度改變表示存在加速度。", "由 F＝ma，合力不能為零。", "粗糙地面摩擦與空氣阻力提供反向合力。", "所以選 B。"], "medium"),
